SELECT CAST(DATE_TRUNC('year', "Sales"."salesdate") AS DATE) AS "Sales Year", CAST(DATE_TRUNC('month', "Sales"."salesdate") AS DATE) AS "Sales Month", CASE WHEN CAST(CASE WHEN CAST(SUM("Sales"."salesamount") AS DECIMAL(18, 2)) = 0 AND ABS(CAST(SUM("Sales"."salesamount") AS DOUBLE)) >= CAST('1E-2' AS DOUBLE) THEN 'OBSL: a value past DECIMAL(18, 2)' ELSE '0' END AS INT) = 0 THEN CAST(SUM("Sales"."salesamount") AS DECIMAL(18, 2)) END AS "Total Sales"
FROM "orionbelt_1"."sales" AS "Sales"
GROUP BY CAST(DATE_TRUNC('year', "Sales"."salesdate") AS DATE), CAST(DATE_TRUNC('month', "Sales"."salesdate") AS DATE)
